def find_kth(arr1, arr2, k):
    def kth_element(a, b, k):
        if not a:
            return b[k - 1]
        if not b:
            return a[k - 1]
        if k == 1:
            return min(a[0], b[0])

        idx_a = min(k // 2, len(a))
        idx_b = k - idx_a
        val_a = a[idx_a - 1]
        val_b = b[idx_b - 1]

        if val_a == val_b:
            return val_a
        elif val_a < val_b:
            return kth_element(a[idx_a:], b, k - idx_a)
        else:
            return kth_element(a, b[idx_b:], k - idx_b)

    return kth_element(arr1, arr2, k)
