def count_Substrings(s):
    def sum_of_digits(sub):
        return sum(int(c) for c in sub)

    n = len(s)
    count = 0

    for i in range(n):
        current_sum = 0
        for j in range(i, n):
            current_sum += int(s[j])
            # Length of substring is (j - i + 1)
            if current_sum == (j - i + 1):
                count += 1

    return count

