assert move_num('abc123def456') == 'abcdef123456'
assert move_num('noNumbersHere') == 'noNumbersHere'
assert move_num('123OnlyNumbersAtStart') == 'OnlyNumbersAtStart123'
assert move_num('EndWithNumbers12345') == 'EndWithNumbers12345'
