def tuple_to_dict(tup):
    """
    Convert a given tuple to a dictionary using adjacent elements as key-value pairs.

    :param tup: Tuple containing an even number of elements
    :return: Dictionary with adjacent elements as key-value pairs
    """
    if len(tup) % 2 != 0:
        raise ValueError("Input tuple must have an even number of elements.")

    return {tup[i]: tup[i + 1] for i in range(0, len(tup), 2)}

# Example usage and test
assert tuple_to_dict((1, 5, 7, 10, 13, 5)) == {1: 5, 7: 10, 13: 5}
```

