def is_polite(num):
    # A polite number is not a power of 2
    return (num & (num - 1)) != 0

def nth_polite_number(n):
    count = 0
    current_number = 1
    while True:
        if is_polite(current_number):
            count += 1
            if count == n:
                return current_number
        current_number += 1

# Example usage and test
assert nth_polite_number(7) == 11
```

