def merge_dictionaries_three(dict1, dict2, dict3):
    # Create a new dictionary by merging all three
    merged_dict = {}

    # Update the dictionaries in the given order
    for d in [dict1, dict2, dict3]:
        merged_dict.update(d)

    return merged_dict

